def apply_discount(cart, code):
    """Apply a discount code to a cart. Codes are a dict {code: (kind, amount)} where kind is
    'percent' or 'fixed'. Returns the new total, never below zero. Unknown codes leave the total unchanged."""
    total = sum(item["price"] * item["qty"] for item in cart["items"])
    codes = {"WELCOME10": ("percent", 10), "FIVEOFF": ("fixed", 5), "HALF": ("percent", 50)}
    if code not in codes:
        return total
    kind, amount = codes[code]
    if kind == "percent":
        total = total * (amount / 100)
    elif kind == "fixed":
        total = total - amount
    return max(total, 0)


def test_apply_discount():
    cart = {"items": [{"price": 20.0, "qty": 2}, {"price": 5.0, "qty": 1}]}
    assert apply_discount(cart, "WELCOME10") == 40.5
    assert apply_discount(cart, "FIVEOFF") == 40.0
    assert apply_discount(cart, "NOPE") == 45.0

